'use client';

import * as React from 'react';
import { cn } from '../../lib/utils';

/**
 * Ported from befui (https://befui.vercel.app/#/components/world-map). befui colours it with theme classes
 * (text-primary, bg-popover …) that don't exist in this app (Tailwind off the CDN, no config), so colours are
 * plain hex / slate classes here, and the tint colour comes in as the `color` prop.
 */

/** True once the element has scrolled into view (immediately for reduced motion / no IntersectionObserver). */
function useChartIn<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [on, setOn] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === 'undefined' || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      setOn(true);
      return;
    }
    const io = new IntersectionObserver(([e]) => { if (e?.isIntersecting) { setOn(true); io.disconnect(); } }, { threshold: 0.2 });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, on] as const;
}

export interface WorldMapDatum {
  /** Country name as in Natural Earth: "India", "United States of America", "Germany". */
  id: string;
  value: number;
  /** Shown in the tooltip instead of `id`. */
  label?: string;
}

interface Country { name: string; c: [number, number]; rings: [number, number][][] }

