let cache: Country[] | undefined;
const countries = () =>
  (cache ??= RAW.map(([name, cx, cy, s]) => ({
    name,
    c: [cx, cy] as [number, number],
    rings: s.split(';').map((r) => {
      const n = r.split(',').map(Number);
      const pts: [number, number][] = [];
      let x = 0, y = 0, shift = 0;
      for (let i = 0; i < n.length; i += 2) {
        const dx = n[i]!;
        x += dx;
        y += n[i + 1]!;
        if (Math.abs(dx) > 1800) shift -= Math.sign(dx) * 3600; // crossed the antimeridian: keep the ring continuous
        pts.push([(x + shift) / 10, y / 10]);
      }
      return pts;
    }),
  })));

/** Names accepted by `data[].id`. */
export const worldCountryNames = () => countries().map((c) => c.name);

/** Adds points so no edge is longer than ~3 degrees; the globe bends straight edges into arcs. */
const densify = (r: [number, number][]) =>
  r.flatMap(([x, y], i) => {
    const [px, py] = r[i - 1] ?? [x, y];
    const n = Math.ceil(Math.max(Math.abs(x - px), Math.abs(y - py)) / 3);
    return Array.from({ length: n }, (_, k) => [px + ((x - px) * (k + 1)) / n, py + ((y - py) * (k + 1)) / n] as [number, number]);
  });

let denseCache: [number, number][][][] | undefined;
const dense = () => (denseCache ??= countries().map((c) => c.rings.map(densify)));

let flatCache: string[] | undefined;
const flatPaths = () =>
  (flatCache ??= countries().map((c) =>
    c.rings
      .flatMap((r) => {
        const xs = r.map(([x]) => x);
        // a ring that runs past +-180 is drawn again one world over, so both edges of the map get their half
        return [0, ...(Math.max(...xs) > 180 ? [-360] : []), ...(Math.min(...xs) < -180 ? [360] : [])].map(
          (o) => 'M' + r.map(([x, y]) => `${(x + o + 180).toFixed(1)} ${(84 - y).toFixed(1)}`).join('L') + 'Z',
        );
      })
      .join(''),
  ));

const R = 100;
const BAR = 26; // tallest bar, in map units
const rad = Math.PI / 180;

/** A bar that reads as a solid: lit front, shaded side, bright top, soft shadow on the ground. */
function Column({ x, y, h, w, hot }: { x: number; y: number; h: number; w: number; hot: boolean }) {
  const d = w * 0.55; // depth, drawn as a slanted offset up and to the right
  const e = d * 0.6;
  const top = y - h;
  const l = x - w / 2, r = x + w / 2;
  return (
    <g className="pointer-events-none" opacity={hot ? 1 : 0.92}>
      <ellipse cx={x + d * 0.5} cy={y} rx={w * 1.1} ry={w * 0.4} fill="#000" fillOpacity={0.35} />
      <path d={`M${l} ${y}V${top}H${r}V${y}Z`} fill="currentColor" />
      <path d={`M${r} ${y}V${top}L${r + d} ${top - e}V${y - e}Z`} fill="currentColor" />
      <path d={`M${r} ${y}V${top}L${r + d} ${top - e}V${y - e}Z`} fill="#000" fillOpacity={0.38} />
      <path d={`M${l} ${top}L${l + d} ${top - e}H${r + d}L${r} ${top}Z`} fill="currentColor" />
      <path d={`M${l} ${top}L${l + d} ${top - e}H${r + d}L${r} ${top}Z`} fill="#fff" fillOpacity={0.45} />
      <path d={`M${l} ${y}V${top}`} stroke="#fff" strokeOpacity={0.25} strokeWidth={0.3} />
    </g>
  );
}

/** Same idea along a direction (the globe's bars lean away from the centre): two shaded halves and a lit cap. */
function Spike({ x, y, x2, y2, w, hot }: { x: number; y: number; x2: number; y2: number; w: number; hot: boolean }) {
  const len = Math.hypot(x2 - x, y2 - y) || 1;
  const nx = (-(y2 - y) / len) * (w / 2), ny = ((x2 - x) / len) * (w / 2);
  return (
    <g className="pointer-events-none" opacity={hot ? 1 : 0.92}>
      <circle cx={x} cy={y} r={w * 0.9} fill="#000" fillOpacity={0.3} />
      <path d={`M${x - nx} ${y - ny}L${x2 - nx} ${y2 - ny}L${x2} ${y2}L${x} ${y}Z`} fill="currentColor" />
      <path d={`M${x + nx} ${y + ny}L${x2 + nx} ${y2 + ny}L${x2} ${y2}L${x} ${y}Z`} fill="currentColor" />
      <path d={`M${x + nx} ${y + ny}L${x2 + nx} ${y2 + ny}L${x2} ${y2}L${x} ${y}Z`} fill="#000" fillOpacity={0.38} />
      <ellipse cx={x2} cy={y2} rx={w / 2} ry={w * 0.3} transform={`rotate(${(Math.atan2(y2 - y, x2 - x) * 180) / Math.PI + 90} ${x2} ${y2})`} fill="currentColor" />
      <ellipse cx={x2} cy={y2} rx={w / 2} ry={w * 0.3} transform={`rotate(${(Math.atan2(y2 - y, x2 - x) * 180) / Math.PI + 90} ${x2} ${y2})`} fill="#fff" fillOpacity={0.45} />
    </g>
  );
}

/** A map pin: teardrop with a hole, lit from the top left, drops in and sends out a ring. Bigger pin = bigger value. */
function Pin({ gid, x, y, r, hot, g, still }: { gid: string; x: number; y: number; r: number; hot: boolean; g: number; still: boolean }) {
  const cy = y - r * 2.3;
  const al = Math.asin(1 / 2.3);
  const tx = r * Math.cos(al), ty = r * Math.sin(al);
  const lift = (1 - g) * r * 4;
  return (
    <g className="pointer-events-none" opacity={g}>
      <ellipse cx={x} cy={y} rx={r * 0.7} ry={r * 0.26} fill="#000" fillOpacity={0.4} />
      <circle cx={x} cy={y} r={r * 0.5} fill="none" stroke="currentColor" strokeWidth={r * 0.1}>
        {!still && <animate attributeName="r" values={`${r * 0.4};${r * 1.8}`} dur="2.4s" repeatCount="indefinite" />}
        {!still && <animate attributeName="stroke-opacity" values="0.7;0" dur="2.4s" repeatCount="indefinite" />}
      </circle>
      <g transform={`translate(0 ${-lift}) scale(${hot ? 1.12 : 1})`} style={{ transformOrigin: `${x}px ${y}px` }}>
        <path d={`M${x} ${y}L${x + tx} ${cy + ty}A${r} ${r} 0 1 0 ${x - tx} ${cy + ty}Z`} fill="currentColor" />
        <path d={`M${x} ${y}L${x + tx} ${cy + ty}A${r} ${r} 0 1 0 ${x - tx} ${cy + ty}Z`} fill={`url(#${gid})`} />
        <circle cx={x} cy={cy} r={r * 0.42} fill="#000" fillOpacity={0.35} />
        <circle cx={x} cy={cy + r * 0.05} r={r * 0.38} fill="#fff" fillOpacity={0.92} />
      </g>
    </g>
  );
}

function useReducedMotion() {
  const [r, setR] = React.useState(false);
  React.useEffect(() => setR(!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches), []);
  return r;
}

const FW = 360, FH = 142; // flat map size in map units
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

/**
 * Countries on a flat map or a spinning globe, with a 3D bar or pin standing on every country in `data` (tall = bigger).
 * Countries with data are tinted by value. Drag to pan the map or turn the globe (arrow keys work too), zoom with the
 * + and - buttons, Ctrl/Cmd + scroll or a double click, hover for a readout.
 * Color it with a text-* class. `onSelect` fires with the country name when you click one that has data.
 */
export function WorldMap({
  data,
  projection = 'flat',
  marker = 'bar',
  zoomable = true,
  legend = true,
  spin = true,
  format = (n) => n.toLocaleString('en-IN'),
  onSelect,
  className,
  label = 'World map',
  color = '#2563eb',
}: {
  data: WorldMapDatum[];
  projection?: 'flat' | 'globe';
  /** What stands on each country: a 3D column or a pin. */
  marker?: 'bar' | 'pin';
  /** Zoom buttons, Ctrl/Cmd + scroll, double click, and panning when zoomed in. */
  zoomable?: boolean;
  /** Clickable list of the countries in `data` under the map. Click one to highlight it (and turn the globe or pan the map to it). */
  legend?: boolean;
  /** Globe turns by itself until you touch it. */
  spin?: boolean;
  format?: (n: number) => string;
  onSelect?: (id: string) => void;
  className?: string;
  label?: string;
  /** Tint colour of countries and markers (any CSS colour). */
  color?: string;
}) {
  const [ref, on] = useChartIn<HTMLDivElement>();
  const reduced = useReducedMotion();
  const gid = 'pin' + React.useId().replace(/:/g, '');
  const globe = projection === 'globe';
  const [rot, setRot] = React.useState({ lon: 20, lat: 18 });
  const [view, setView] = React.useState({ k: 1, x: 0, y: 0 }); // k = zoom; x, y = top-left of the flat view in map units
  const [t, setT] = React.useState(0);
  const [hover, setHover] = React.useState<string | null>(null);
  const [sel, setSel] = React.useState<string | null>(null);
  const [tip, setTip] = React.useState<{ x: number; y: number } | null>(null);
  const drag = React.useRef<{ x: number; y: number; sx: number; sy: number; el: Element; id: number; moved: boolean } | null>(null);
  const idle = React.useRef(false);
  const k = view.k;
  const ms = 1 / k ** 0.6; // markers shrink a little as you zoom in, so they do not swallow the map

  const list = countries();
  const byId = new Map(data.map((d) => [d.id, d]));
  const max = Math.max(...data.map((d) => d.value), 1);

  // flat view box and zoom around a point given as 0..1 of the box
  const vw = FW / k, vh = FH / k;
  const maxK = globe ? 3 : 8;
  React.useEffect(() => setView({ k: 1, x: 0, y: 0 }), [globe]);
  const zoomTo = (nk: number, fx = 0.5, fy = 0.5) =>
    setView((v) => {
      nk = clamp(nk, 1, maxK);
      const w = FW / nk, h = FH / nk;
      return { k: nk, x: clamp(v.x + fx * (FW / v.k) - fx * w, 0, FW - w), y: clamp(v.y + fy * (FH / v.k) - fy * h, 0, FH - h) };
    });

  // Ctrl/Cmd + scroll (and trackpad pinch) zooms; plain scroll still scrolls the page
  React.useEffect(() => {
    const el = ref.current;
    if (!zoomable || !el) return;
    const wheel = (e: WheelEvent) => {
      if (!e.ctrlKey && !e.metaKey) return;
      e.preventDefault();
      const b = el.getBoundingClientRect();
      zoomTo(k * Math.exp(-e.deltaY * 0.01), (e.clientX - b.left) / b.width, (e.clientY - b.top) / b.height);
    };
    el.addEventListener('wheel', wheel, { passive: false });
    return () => el.removeEventListener('wheel', wheel);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [zoomable, k]);

  // bars grow once the map scrolls into view
  React.useEffect(() => {
    if (!on) return;
    if (reduced) return setT(1);
    const start = performance.now();
    let raf = requestAnimationFrame(function tick(now) {
      const p = Math.min((now - start) / 1400, 1);
      setT(p);
      if (p < 1) raf = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(raf);
  }, [on, reduced]);

  // globe turns by itself until it is touched
  React.useEffect(() => {
    if (!globe || !spin || reduced) return;
    let last = performance.now();
    let raf = requestAnimationFrame(function tick(now) {
      if (!idle.current && !drag.current) setRot((r) => ({ ...r, lon: (r.lon + (now - last) * 0.008) % 360 }));
      last = now;
      raf = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(raf);
  }, [globe, spin, reduced]);

  const grow = (i: number) => {
    const p = Math.min(Math.max(t * 1.5 - i * 0.04, 0), 1);
    return 1 - (1 - p) ** 3;
  };

  // projection
  const sl = Math.sin(rot.lat * rad), cl = Math.cos(rot.lat * rad);
  const proj = (lon: number, lat: number) => {
    const a = (lon - rot.lon) * rad, p = lat * rad;
    const ca = Math.cos(a), cp = Math.cos(p);
    const z = sl * Math.sin(p) + cl * cp * ca;
    return { x: R * cp * Math.sin(a), y: -R * (cl * Math.sin(p) - sl * cp * ca), z };
  };

  const globePaths = React.useMemo(() => {
    if (!globe) return [];
    return dense().map((rings) => {
      let seen = false;
      const d = rings
        .map((r) => {
          const pts = r.map(([lon, lat]) => {
            const p = proj(lon, lat);
            if (p.z > 0) { seen = true; return `${p.x.toFixed(1)} ${p.y.toFixed(1)}`; }
            const k = R / (Math.hypot(p.x, p.y) || 1); // behind the horizon: pin to the edge of the disc
            return `${(p.x * k).toFixed(1)} ${(p.y * k).toFixed(1)}`;
          });
          return 'M' + pts.join('L') + 'Z';
        })
        .join('');
      return seen ? d : '';
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [globe, rot.lon, rot.lat]);

  const tint = (name: string) => {
    const d = byId.get(name);
    const base = d ? 0.28 + 0.4 * (d.value / max) : 0.1;
    return name === hover || name === sel ? Math.min(base + 0.22, 0.95) : base;
  };

  const countryProps = (c: Country) => {
    const d = byId.get(c.name);
    return {
      fill: 'currentColor',
      fillOpacity: tint(c.name),
      stroke: c.name === sel ? '#0f172a' : '#ffffff',
      className: cn('transition-[fill-opacity] duration-150', d && 'cursor-pointer'),
      strokeWidth: c.name === sel ? 1.4 : 0.5,
      vectorEffect: 'non-scaling-stroke' as const,
      strokeLinejoin: 'round' as const,
      onPointerEnter: () => setHover(c.name),
      onPointerLeave: () => setHover(null),
      onClick: d && !drag.current?.moved ? () => pick(c.name) : undefined,
    };
  };

  const bars = data
    .map((d, i) => ({ d, c: list.find((c) => c.name === d.id), i }))
    .filter((b): b is { d: WorldMapDatum; c: Country; i: number } => !!b.c);

  const lit = (n: string) => n === hover || n === sel;
  // click a country (map or list): highlight it, bring it into view, tell the parent. Click it again to clear.
  const pick = (name: string) => {
    const next = sel === name ? null : name;
    setSel(next);
    const c = next && list.find((x) => x.name === next);
    if (c) {
      idle.current = true;
      if (globe) setRot({ lon: c.c[0], lat: clamp(c.c[1], -60, 60) });
      else setView((v) => {
        const nk = Math.max(v.k, 2.5), w = FW / nk, h = FH / nk;
        return { k: nk, x: clamp(c.c[0] + 180 - w / 2, 0, FW - w), y: clamp(84 - c.c[1] - h / 2, 0, FH - h) };
      });
      onSelect?.(c.name);
    }
  };

  const hovered = hover ? byId.get(hover) : undefined;
  const tipText = hover ? `${hovered?.label ?? hover}${hovered ? `: ${format(hovered.value)}` : ''}` : '';

  const down = (e: React.PointerEvent) => {
    drag.current = { x: e.clientX, y: e.clientY, sx: e.clientX, sy: e.clientY, el: e.currentTarget, id: e.pointerId, moved: false };
    idle.current = true;
  };
  const up = () => {
    const d = drag.current;
    // keep `moved` for one tick so the click that ends a drag does not count as a selection
    setTimeout(() => { if (drag.current === d) drag.current = null; });
  };
  const move = (e: React.PointerEvent) => {
    const box = e.currentTarget.getBoundingClientRect();
    setTip({ x: e.clientX - box.left, y: e.clientY - box.top });
    const d = drag.current;
    if (!d) return;
    if (!d.moved && Math.hypot(e.clientX - d.sx, e.clientY - d.sy) > 3) { d.moved = true; d.el.setPointerCapture(d.id); setHover(null); }
    if (!d.moved) return;
    const dx = e.clientX - d.x, dy = e.clientY - d.y;
    d.x = e.clientX;
    d.y = e.clientY;
    if (globe) setRot((r) => ({ lon: r.lon - (dx * 0.4) / k, lat: clamp(r.lat + (dy * 0.4) / k, -70, 70) }));
    else setView((v) => ({ ...v, x: clamp(v.x - (dx * vw) / box.width, 0, FW - vw), y: clamp(v.y - (dy * vh) / (box.width * (FH / FW)), 0, FH - vh) }));
  };

  const mark = (key: string, x: number, y: number, x2: number, y2: number, hot: boolean, v: number, g: number, o = 1) => (
    <g key={key} opacity={o}>
      {marker === 'pin' ? (
        <Pin gid={gid} x={x} y={y} r={(2.2 + 2 * v) * ms} hot={hot} g={g} still={reduced} />
      ) : globe ? (
        <Spike x={x} y={y} x2={x2} y2={y2} w={(hot ? 4.4 : 3.6) * ms} hot={hot} />
      ) : (
        <Column x={x} y={y} h={y - y2} w={(hot ? 4 : 3.2) * ms} hot={hot} />
      )}
    </g>
  );

  const defs = (
    <defs>
      <radialGradient id={gid} cx="0.35" cy="0.3" r="0.8">
        <stop offset="0" stopColor="#fff" stopOpacity={0.9} />
        <stop offset="0.35" stopColor="#fff" stopOpacity={0} />
        <stop offset="0.7" stopColor="#000" stopOpacity={0} />
        <stop offset="1" stopColor="#000" stopOpacity={0.5} />
      </radialGradient>
    </defs>
  );

  const btn = 'grid h-7 w-7 place-items-center rounded-md border border-slate-200 bg-white/80 text-sm text-slate-700 backdrop-blur transition-colors hover:bg-slate-100 disabled:opacity-40 disabled:hover:bg-white/80';
  const zoomed = k > 1;

  return (
    <div className={cn(globe ? 'mx-auto w-full max-w-md' : 'w-full', className)} style={{ color }}>
    <div
      ref={ref}
      className={cn('relative', globe && 'aspect-square overflow-hidden')}
      onPointerMove={move}
      onPointerLeave={() => setTip(null)}
      onDoubleClick={(e) => {
        if (!zoomable) return;
        const b = e.currentTarget.getBoundingClientRect();
        zoomTo(k * 1.8, (e.clientX - b.left) / b.width, (e.clientY - b.top) / b.height);
      }}
    >
      {globe ? (
        <svg
          viewBox={`${-112 / k} ${-112 / k} ${224 / k} ${224 / k}`}
          role="img"
          aria-label={label}
          tabIndex={0}
          className="size-full cursor-grab touch-none select-none outline-none focus-visible:ring-2 focus-visible:ring-blue-500 active:cursor-grabbing"
          onPointerDown={down}
          onPointerUp={up}
          onKeyDown={(e) => {
            const s = { ArrowLeft: [-10, 0], ArrowRight: [10, 0], ArrowUp: [0, 8], ArrowDown: [0, -8] }[e.key];
            if (!s) return;
            e.preventDefault();
            idle.current = true;
            setRot((r) => ({ lon: r.lon + s[0]!, lat: clamp(r.lat + s[1]!, -70, 70) }));
          }}
        >
          {defs}
          <circle r={R} fill="currentColor" fillOpacity={0.05} stroke="currentColor" strokeOpacity={0.25} strokeWidth={0.5} vectorEffect="non-scaling-stroke" />
          {list.map((c, i) => globePaths[i] && <path key={c.name} d={globePaths[i]} fillRule="evenodd" {...countryProps(c)} />)}
          {[...bars]
            .map((b) => ({ ...b, p: proj(b.c.c[0], b.c.c[1]) }))
            .filter((b) => b.p.z > 0.05)
            .sort((a, b) => a.p.y - b.p.y)
            .map(({ d, c, i, p }) => {
              const h = 1 + ((d.value / max) * BAR * ms * grow(i)) / R;
              return mark(c.name, p.x, p.y, p.x * h, p.y * h, lit(c.name), d.value / max, grow(i), Math.min(p.z * 3, 1));
            })}
        </svg>
      ) : (
        <svg
          viewBox={`${view.x} ${view.y} ${vw} ${vh}`}
          role="img"
          aria-label={label}
          className={cn('block h-auto w-full select-none', zoomed && 'cursor-grab touch-none active:cursor-grabbing')}
          onPointerDown={zoomed ? down : undefined}
          onPointerUp={up}
        >
          {defs}
          {list.map((c, i) => <path key={c.name} d={flatPaths()[i]} fillRule="evenodd" {...countryProps(c)} />)}
          {[...bars].sort((a, b) => b.c.c[1] - a.c.c[1]).map(({ d, c, i }) => {
            const x = c.c[0] + 180, y = 84 - c.c[1];
            return mark(c.name, x, y, x, y - (d.value / max) * BAR * ms * grow(i), lit(c.name), d.value / max, grow(i));
          })}
        </svg>
      )}
      {zoomable && (
        <div className="absolute right-2 top-2 grid gap-1" onDoubleClick={(e) => e.stopPropagation()}>
          <button type="button" aria-label="Zoom in" className={btn} disabled={k >= maxK} onClick={() => zoomTo(k * 1.6)}>+</button>
          <button type="button" aria-label="Zoom out" className={btn} disabled={k <= 1} onClick={() => zoomTo(k / 1.6)}>−</button>
          <button type="button" aria-label="Reset view" className={btn} disabled={!zoomed} onClick={() => setView({ k: 1, x: 0, y: 0 })}>⟲</button>
        </div>
      )}
      {hover && tip && (
        <div
          role="status"
          className="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-full whitespace-nowrap rounded-md border border-slate-200 bg-white px-2 py-1 text-xs font-medium tabular-nums text-slate-800 shadow-sm"
          style={{ left: tip.x, top: tip.y - 10 }}
        >
          {tipText}
        </div>
      )}
    </div>
      <ul className={cn(legend ? 'mt-3 grid gap-x-6 sm:grid-cols-2' : 'sr-only')}>
        {[...data].sort((a, b) => b.value - a.value).map((d) => (
          <li key={d.id}>
            <button
              type="button"
              aria-pressed={sel === d.id}
              onClick={() => pick(d.id)}
              onPointerEnter={() => { setHover(d.id); setTip(null); }}
              onPointerLeave={() => setHover(null)}
              className={cn(
                'flex w-full items-center justify-between gap-3 rounded-md px-2 py-1 text-left text-xs font-medium text-slate-800 transition-colors hover:bg-slate-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500',
                sel === d.id && 'bg-blue-50 text-blue-700',
              )}
            >
              {d.label ?? d.id}
              <span className="tabular-nums text-slate-500">{format(d.value)}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default WorldMap;
